// Picks the TunaOS Media Writer build for the visitor's computer. The release
// assets are listed in iso.tunaos.org/downloads.json under mediaWriter.assets,
// keyed by the ids in AssetKey (generated by tuna-os/iso-builder
// scripts/generate-downloads.py).

export type AssetKey = 'windows-x64' | 'macos' | 'linux-x86_64' | 'linux-aarch64';

export type Platform =
  | {kind: 'windows'; asset: 'windows-x64'}
  | {kind: 'macos'; asset: 'macos'}
  | {kind: 'linux'; asset: 'linux-x86_64' | 'linux-aarch64'}
  | {kind: 'mobile'}
  | {kind: 'unknown'};

export type MediaWriterAsset = {url: string; size?: number; signed?: boolean};

export type MediaWriterRelease = {
  version?: string;
  assets: Partial<Record<AssetKey, MediaWriterAsset>>;
};

export type ClientHints = {
  userAgent: string;
  // navigator.platform; iPadOS reports "MacIntel" with a desktop user agent.
  platform?: string;
  maxTouchPoints?: number;
};

export const OS_LABEL: Record<'windows' | 'macos' | 'linux', string> = {
  windows: 'Windows',
  macos: 'macOS',
  linux: 'Linux',
};

export function detectPlatform({userAgent, platform = '', maxTouchPoints = 0}: ClientHints): Platform {
  const ua = userAgent;
  // Android and iOS user agents also contain "Linux" or "Mac OS X", so test
  // for phones and tablets first.
  if (/Android|iPhone|iPad|iPod|Mobile|Silk|Kindle/i.test(ua)) return {kind: 'mobile'};
  if (platform === 'MacIntel' && maxTouchPoints > 1) return {kind: 'mobile'};
  if (/Windows/i.test(ua)) return {kind: 'windows', asset: 'windows-x64'};
  if (/Macintosh|Mac OS X/i.test(ua)) return {kind: 'macos', asset: 'macos'};
  // ChromeOS cannot install a Flatpak outside its Linux container; send it to
  // the browser builder rather than guess.
  if (/CrOS/i.test(ua)) return {kind: 'unknown'};
  if (/Linux|X11/i.test(ua)) {
    const arm = /aarch64|arm64|armv8/i.test(`${ua} ${platform}`);
    return {kind: 'linux', asset: arm ? 'linux-aarch64' : 'linux-x86_64'};
  }
  return {kind: 'unknown'};
}

const ASSET_KEYS: readonly AssetKey[] = ['windows-x64', 'macos', 'linux-x86_64', 'linux-aarch64'];

// Reads one property of an untrusted JSON value; undefined unless it is an object with that key.
function field(value: unknown, key: string): unknown {
  return value && typeof value === 'object' && key in value ? Reflect.get(value, key) : undefined;
}

// Returns the mediaWriter block of downloads.json, or null when it does not
// have the expected shape.
export function parseMediaWriter(doc: unknown): MediaWriterRelease | null {
  const mw = field(doc, 'mediaWriter');
  const assets = field(mw, 'assets');
  if (!assets || typeof assets !== 'object') return null;
  const out: MediaWriterRelease['assets'] = {};
  for (const key of ASSET_KEYS) {
    const entry = field(assets, key);
    const url = field(entry, 'url');
    if (typeof url !== 'string' || !url.startsWith('https://')) continue;
    const size = field(entry, 'size');
    const signed = field(entry, 'signed');
    out[key] = {
      url,
      size: typeof size === 'number' ? size : undefined,
      signed: typeof signed === 'boolean' ? signed : undefined,
    };
  }
  const version = field(mw, 'version');
  return {version: typeof version === 'string' ? version : undefined, assets: out};
}

export function formatSize(bytes: number): string {
  return `${Math.max(1, Math.round(bytes / 1e6))} MB`;
}
